using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.EntityFrameworkCore;
using ToolsApp.Api.Contracts;
using ToolsApp.Api.Data;

namespace ToolsApp.Api.Endpoints
{
    public static class ColorSearchEndpoints
    {
        public static IEndpointRouteBuilder MapColorSearchEndpoints(this IEndpointRouteBuilder app)
        {
            app.MapGet("/api/colors/search", SearchColorsAsync).WithTags("Colors");
            return app;
        }

        // GET /api/colors/search?q=sea matches names case-insensitively, or hex values.
        private static async Task<Ok<List<ColorDto>>> SearchColorsAsync(string? q, ToolsAppDbContext db, CancellationToken cancellationToken)
        {
          var colors = await db.Colors.Include(c => c.Palette).AsNoTracking().ToListAsync();  
          var matches = colors
                .Where(c => c.Name.ToLower().Contains(q.ToLower()) || c.Hex.Contains(q.ToUpper()))
                .OrderBy(c => c.Name)
                .Select(c => c.ToDto())
                .ToList();
          return TypedResults.Ok(matches);
        }
    }
}
